const https = require('https');
const bizno = process.argv[2];

https.get(`https://bizno.net/article/${bizno}`, { headers: { 'User-Agent': 'Mozilla/5.0' } }, res => {
  let data = '';
  res.on('data', chunk => data += chunk);
  res.on('end', () => {
    const lines = data.split('\n');
    lines.forEach((l, i) => {
      if (l.includes('meta name="description"') || l.includes('meta name="keywords"') || l.includes('전화번호') || l.includes('010-') || l.includes('051-')) {
        console.log((i+1) + ': ' + l.trim());
      }
    });
  });
}).on('error', err => console.error(err));

const https = require('https');
const fs = require('fs');

const missing = JSON.parse(fs.readFileSync('brain_logs/scratch/missing_59.json', 'utf-8'));

function fetchBizno(bizno) {
  return new Promise((resolve) => {
    const clean = bizno.replace(/[^0-9]/g, '');
    if (!clean || clean.length !== 10) {
      return resolve({ bizno, status: 'INVALID_BIZNO', phone: null, rawPhone: null });
    }
    const req = https.get(`https://bizno.net/article/${clean}`, { headers: { 'User-Agent': 'Mozilla/5.0' }, timeout: 8000 }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        let isClosed = data.includes('폐업자');
        let isActive = data.includes('계속사업자');
        let status = isClosed ? '폐업자' : (isActive ? '계속사업자' : '알수없음');

        // Check meta description for phone
        let metaPhone = null;
        const metaDescMatch = data.match(/<meta\s+name="description"\s+content="([^"]+)"/i);
        if (metaDescMatch) {
          const desc = metaDescMatch[1];
          const m = desc.match(/전화번호\s*:\s*([0-9\-*]+)/);
          if (m) metaPhone = m[1].trim();
        }

        // Check table body phone
        let tablePhone = null;
        const phoneIdx = data.indexOf('<th>전화번호</th>');
        if (phoneIdx !== -1) {
          const chunk = data.substring(phoneIdx, phoneIdx + 300);
          const tdMatch = chunk.match(/<td>([\s\S]*?)<\/td>/i);
          if (tdMatch) {
            let cleanTd = tdMatch[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
            cleanTd = cleanTd.split('\n')[0].trim();
            if (cleanTd && !cleanTd.includes('※')) {
              tablePhone = cleanTd;
            } else if (cleanTd) {
              tablePhone = cleanTd;
            }
          }
        }

        resolve({
          bizno,
          status,
          metaPhone,
          tablePhone
        });
      });
    });
    req.on('error', (err) => resolve({ bizno, status: 'ERROR', error: err.message, metaPhone: null, tablePhone: null }));
    req.on('timeout', () => { req.destroy(); resolve({ bizno, status: 'TIMEOUT', metaPhone: null, tablePhone: null }); });
  });
}

async function run() {
  console.log(`Starting Bizno scan for ${missing.length} companies...`);
  const results = [];
  for (let i = 0; i < missing.length; i++) {
    const item = missing[i];
    console.log(`[${i+1}/${missing.length}] Scanning ${item.comp} (${item.bizno})...`);
    const bResult = await fetchBizno(item.bizno);
    results.push({
      ...item,
      biznoStatus: bResult.status,
      biznoMetaPhone: bResult.metaPhone,
      biznoTablePhone: bResult.tablePhone
    });
    // slight delay
    await new Promise(r => setTimeout(r, 400));
  }
  fs.writeFileSync('brain_logs/scratch/bizno_scan_59.json', JSON.stringify(results, null, 2), 'utf-8');
  console.log('Finished scanning all 59 companies!');
}

run();

const https = require('https');
const fs = require('fs');

const missing = JSON.parse(fs.readFileSync('brain_logs/scratch/missing_59.json', 'utf-8'));

function fetchBizno(bizno) {
  return new Promise((resolve) => {
    const clean = bizno.replace(/[^0-9]/g, '');
    if (!clean || clean.length !== 10) {
      return resolve({ bizno, status: 'INVALID_BIZNO', metaPhone: null, tablePhone: null, rawTd: null });
    }
    const req = https.get(`https://bizno.net/article/${clean}`, { headers: { 'User-Agent': 'Mozilla/5.0' }, timeout: 8000 }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        // Status from Hometax real-time
        let status = '알수없음';
        const statusMatch = data.match(/사업자 현재 상태[^\:]*\:\s*([^\s<]+)/);
        if (statusMatch) {
          status = statusMatch[1].trim();
        }

        // Meta phone
        let metaPhone = null;
        const metaMatch = data.match(/전화번호\s*:\s*([0-9\-*]+)/);
        if (metaMatch) {
          metaPhone = metaMatch[1].trim();
        }

        // Table phone
        let tablePhone = null;
        let rawTd = null;
        const pIdx = data.indexOf('<th>전화번호</th>');
        if (pIdx !== -1) {
          const chunk = data.substring(pIdx, pIdx + 300);
          const tdMatch = chunk.match(/<td>([\s\S]*?)<\/td>/i);
          if (tdMatch) {
            rawTd = tdMatch[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
            const phoneExtract = rawTd.match(/([0-9]{2,4}-[0-9]{3,4}-[0-9*]{4})/);
            if (phoneExtract) {
              tablePhone = phoneExtract[1].trim();
            }
          }
        }

        resolve({
          bizno,
          status,
          metaPhone,
          tablePhone,
          rawTd
        });
      });
    });
    req.on('error', (err) => resolve({ bizno, status: 'ERROR', error: err.message, metaPhone: null, tablePhone: null, rawTd: null }));
    req.on('timeout', () => { req.destroy(); resolve({ bizno, status: 'TIMEOUT', metaPhone: null, tablePhone: null, rawTd: null }); });
  });
}

async function run() {
  console.log(`Starting precise Bizno scan for ${missing.length} companies...`);
  const results = [];
  for (let i = 0; i < missing.length; i++) {
    const item = missing[i];
    const bResult = await fetchBizno(item.bizno);
    results.push({
      ...item,
      biznoStatus: bResult.status,
      biznoMetaPhone: bResult.metaPhone,
      biznoTablePhone: bResult.tablePhone,
      rawTd: bResult.rawTd
    });
    console.log(`[${i+1}/${missing.length}] ${item.comp} (${item.bizno}) -> 상태: ${bResult.status} | 전화: ${bResult.tablePhone || bResult.metaPhone || '없음'}`);
    await new Promise(r => setTimeout(r, 350));
  }
  fs.writeFileSync('brain_logs/scratch/bizno_scan_59_precise.json', JSON.stringify(results, null, 2), 'utf-8');
  console.log('Finished precise scanning!');
}

run();

const fs = require('fs');

const scan = JSON.parse(fs.readFileSync('brain_logs/scratch/bizno_scan_59_precise.json', 'utf-8'));
const vMap = JSON.parse(fs.readFileSync('brain_logs/scratch/verified_map.json', 'utf-8'));

